window.__PIONEER_REGISTER_TEST("TEST_HIST_SET_48", [
  {"q":"[UPSC Prelims पैटर्न — जनजातीय-किसान विद्रोह एवं नेतृत्व] निम्नलिखित युग्मों पर विचार कीजिए:\n1. रम्पा विद्रोह (1922-24) : अल्लूरी सीताराम राजू\n2. ताना भगत आंदोलन (1914) : जतरा भगत (जतरा उराँव)\n3. पाइक विद्रोह (ओडिशा, 1817) : दक्कन कृषक राहत अधिनियम, 1879\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (मद्रास वन अधिनियम 1882 व बेगार के विरुद्ध अल्लूरी सीताराम राजू ने सशस्त्र गुरिल्ला युद्ध लड़ा।) युग्म 2 सही (उराँव जनजाति में एकेश्वरवाद, मद्य-त्याग व कर-न-देने वाले अहिंसक ताना भगत आंदोलन के जनक जतरा भगत थे।) युग्म 3 गलत (सही: पाइक विद्रोह (ओडिशा, 1817) — बख्शी जगबंधु विद्याधर)।"},
  {"q":"[UPSC Prelims पैटर्न — प्राचीन ग्रंथ एवं रचयिता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. ब्रह्मस्फुटसिद्धांत : ब्रह्मगुप्त\n2. मत्तविलासप्रहसन : कल्हण\n3. राजतरंगिणी : सीतलै सतनार\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (भीनमाल (राजस्थान) के गणितज्ञ ब्रह्मगुप्त ने 628 ई. में 'ब्रह्मस्फुटसिद्धांत' रचा।) युग्म 2 गलत (सही: मत्तविलासप्रहसन — महेंद्रवर्मन प्रथम)। युग्म 3 गलत (सही: राजतरंगिणी — कल्हण)।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख आयोग एवं उद्देश्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बटलर समिति (1927) : ब्रिटिश क्राउन व भारतीय देसी रियासतों के मध्य संबंध\n2. फ्लाउड आयोग (Floud Commission) : बंगाल में स्थायी बंदोबस्त (जमींदारी) की समाप्ति की सिफारिश व बटाईदारों को 2/3 हिस्सा\n3. हंटर शिक्षा आयोग (1882) : पुलिस प्रशासन व प्रांतीय CID सुधार (कर्जन)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (सर हरकोर्ट बटलर की अध्यक्षता वाली समिति ने कहा कि देसी रियासतें बिना सहमति ब्रिटिश भारतीय उत्तरदायी सरकार को न सौंपी जाएँ।) युग्म 2 सही (सर फ्रांसिस फ्लाउड आयोग ने तेभागा (बटाईदारों को उपज का 2/3 भाग) की सिफारिश की जिससे 1946 का तेभागा आंदोलन प्रेरित हुआ।) युग्म 3 गलत (सही: हंटर शिक्षा आयोग (1882) — प्राथमिक एवं माध्यमिक शिक्षा की स्थिति की जाँच)।"},
  {"q":"[UPSC CDS PYQ] 'मुत्सद्दी नीति' के अंतर्गत लॉर्ड कॉर्नवालिस के बाद किस गवर्नर-जनरल ने अवध के नवाब के साथ 'सहायक संधि' (1801) करके आधे अवध क्षेत्र को अपने अधीन किया?","options":["सर जॉन शोर","लॉर्ड हेस्टिंग्स","लॉर्ड वेलेजली","लॉर्ड मिंटो प्रथम"],"correct":2,"explanation":"लॉर्ड वेलेजली ने 1801 ई. में अवध के नवाब सआदत अली खाँ से सहायक संधि करवाकर रोहिलखंड व निचले दोआब सहित आधा अवध छीन लिया।"},
  {"q":"[UPSC Prelims पैटर्न — महाजनपद एवं राजधानियाँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. कोसल महाजनपद : पोटली (पोतन)\n2. अश्मक महाजनपद : कौशाम्बी\n3. वत्स महाजनपद : चंपा\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: कोसल महाजनपद — श्रावस्ती)। युग्म 2 गलत (सही: अश्मक महाजनपद — पोटली (पोतन))। युग्म 3 गलत (सही: वत्स महाजनपद — कौशाम्बी)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — मध्यकालीन ग्रंथ एवं लेखक] सूची-I को सूची-II से सुमेलित कीजिए:\nA. पद्मावत (अवधी, 1540)   |   1. मिर्जा मुहम्मद (औरंगजेब काल)\nB. फतवा-ए-जहाँदारी   |   2. मोतमिद खाँ\nC. इकबालनामा-ए-जहाँगीरी   |   3. मलिक मुहम्मद जायसी\nD. तुहफत-उल-हिन्द   |   4. जियाउद्दीन बरनी","options":["A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-1, D-2"],"correct":0,"explanation":"सही सुमेलन: पद्मावत (अवधी, 1540) (मलिक मुहम्मद जायसी), फतवा-ए-जहाँदारी (जियाउद्दीन बरनी), इकबालनामा-ए-जहाँगीरी (मोतमिद खाँ), तुहफत-उल-हिन्द (मिर्जा मुहम्मद (औरंगजेब काल))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — वैदिक शब्दावली एवं उपनिषद] सूची-I को सूची-II से सुमेलित कीजिए:\nA. निष्क व शतमन   |   1. छान्दोग्य उपनिषद\nB. अघन्या   |   2. मुद्रा/मूल्य की इकाइयाँ\nC. तत्त्वमसि संवाद (उद्दालक-श्वेतकेतु)   |   3. गेहूँ\nD. गोधूम   |   4. गाय (न मारे जाने योग्य)","options":["A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3"],"correct":2,"explanation":"सही सुमेलन: निष्क व शतमन (मुद्रा/मूल्य की इकाइयाँ), अघन्या (गाय (न मारे जाने योग्य)), तत्त्वमसि संवाद (उद्दालक-श्वेतकेतु) (छान्दोग्य उपनिषद), गोधूम (गेहूँ)।"},
  {"q":"[UPSC Prelims पैटर्न — वैदिक शब्दावली एवं उपनिषद] निम्नलिखित युग्मों पर विचार कीजिए:\n1. निष्क व शतमन : गेहूँ\n2. गोधूम : छान्दोग्य उपनिषद\n3. तत्त्वमसि संवाद (उद्दालक-श्वेतकेतु) : तैत्तिरीय उपनिषद\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: निष्क व शतमन — मुद्रा/मूल्य की इकाइयाँ)। युग्म 2 गलत (सही: गोधूम — गेहूँ)। युग्म 3 गलत (सही: तत्त्वमसि संवाद (उद्दालक-श्वेतकेतु) — छान्दोग्य उपनिषद)।"},
  {"q":"[UPSC Prelims पैटर्न — महाजनपद एवं राजधानियाँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. कुरु महाजनपद : इंद्रप्रस्थ\n2. कोसल महाजनपद : श्रावस्ती\n3. मत्स्य महाजनपद : मथुरा\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (मेरठ-दिल्ली क्षेत्र में स्थित कुरु महाजनपद की राजधानी इंद्रप्रस्थ थी।) युग्म 2 सही (प्रसेनजित के कोसल महाजनपद की राजधानी श्रावस्ती थी (दक्षिणी भाग कुशावती)।) युग्म 3 गलत (सही: मत्स्य महाजनपद — विराटनगर (बैराठ))।"},
  {"q":"[UPSC Prelims पैटर्न — मध्यकालीन ग्रंथ एवं लेखक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. तुहफत-उल-हिन्द : अब्दुर्रहीम खानखाना एवं रसखान (हिंदी-ब्रज काव्य)\n2. रहीम दोहावली / प्रेमवाटिका : इब्राहिम आदिल शाह द्वितीय (बीजापुर)\n3. किताब-ए-नवरस : मोतमिद खाँ\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: तुहफत-उल-हिन्द — मिर्जा मुहम्मद (औरंगजेब काल))। युग्म 2 गलत (सही: रहीम दोहावली / प्रेमवाटिका — अब्दुर्रहीम खानखाना एवं रसखान (हिंदी-ब्रज काव्य))। युग्म 3 गलत (सही: किताब-ए-नवरस — इब्राहिम आदिल शाह द्वितीय (बीजापुर))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — क्रांतिकारी घटनाएँ एवं नायक] सूची-I को सूची-II से सुमेलित कीजिए:\nA. दिल्ली षड्यंत्र केस (1912)   |   1. खुदीराम बोस एवं प्रफुल्ल चाकी\nB. काकोरी कांड (9 अगस्त 1925)   |   2. मदनलाल धींगरा\nC. कर्जन वायली वध (लंदन, 1909)   |   3. रासबिहारी बोस (अमीरचंद, अवध बिहारी, बसंत विश्वास)\nD. मुजफ्फरपुर बम कांड (1908)   |   4. HRA (रामप्रसाद बिस्मिल, अशफाकुल्ला, रोशन, राजेंद्र लाहिड़ी)","options":["A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-3, B-2, C-4, D-1","A-4, B-3, C-2, D-1"],"correct":0,"explanation":"सही सुमेलन: दिल्ली षड्यंत्र केस (1912) (रासबिहारी बोस (अमीरचंद, अवध बिहारी, बसंत विश्वास)), काकोरी कांड (9 अगस्त 1925) (HRA (रामप्रसाद बिस्मिल, अशफाकुल्ला, रोशन, राजेंद्र लाहिड़ी)), कर्जन वायली वध (लंदन, 1909) (मदनलाल धींगरा), मुजफ्फरपुर बम कांड (1908) (खुदीराम बोस एवं प्रफुल्ल चाकी)।"},
  {"q":"[UPSC Prelims पैटर्न — स्वतंत्रता संग्राम की पुस्तकें] निम्नलिखित युग्मों पर विचार कीजिए:\n1. अनहैप्पी इंडिया (1928) : विनायक दामोदर सावरकर\n2. द इंडियन वार ऑफ इंडिपेंडेंस 1857 : नेताजी सुभाष चंद्र बोस\n3. द इंडियन स्ट्रगल : महात्मा गांधी (लंदन से दक्षिण अफ्रीका जहाज पर)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: अनहैप्पी इंडिया (1928) — लाला लाजपत राय)। युग्म 2 गलत (सही: द इंडियन वार ऑफ इंडिपेंडेंस 1857 — विनायक दामोदर सावरकर)। युग्म 3 गलत (सही: द इंडियन स्ट्रगल — नेताजी सुभाष चंद्र बोस)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — महाजनपद एवं राजधानियाँ] सूची-I को सूची-II से सुमेलित कीजिए:\nA. वत्स महाजनपद   |   1. शुक्तिमती\nB. अंग महाजनपद   |   2. इंद्रप्रस्थ\nC. कुरु महाजनपद   |   3. कौशाम्बी\nD. चेदि महाजनपद   |   4. चंपा","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1"],"correct":2,"explanation":"सही सुमेलन: वत्स महाजनपद (कौशाम्बी), अंग महाजनपद (चंपा), कुरु महाजनपद (इंद्रप्रस्थ), चेदि महाजनपद (शुक्तिमती)।"},
  {"q":"[UPSC CDS PYQ] निम्नलिखित प्राचीन भारतीय शासकों का सही कालानुक्रम (पहले से बाद) क्या है?\n1. बिम्बिसार  2. चंद्रगुप्त मौर्य  3. कनिष्क  4. हर्षवर्धन","options":["1 - 2 - 3 - 4","1 - 2 - 4 - 3","1 - 3 - 2 - 4","2 - 1 - 3 - 4"],"correct":0,"explanation":"बिम्बिसार (हर्यक वंश, 544 ई.पू.) -> चंद्रगुप्त मौर्य (322 ई.पू.) -> कनिष्क (कुषाण, 78 ई.) -> हर्षवर्धन (वर्धन वंश, 606 ई.)।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बसीन की संधि (1802 ई.) : पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना\n2. पेरिस की संधि (1763 ई.) : प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी\n3. एक्स-ला-शैपल की संधि (1748 ई.) : प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (1802 की बसीन संधि के अंतर्गत पेशवा बाजीराव द्वितीय ने कंपनी की सहायक सेना व पूना में ब्रिटिश संरक्षण स्वीकार किया।) युग्म 2 गलत (सही: पेरिस की संधि (1763 ई.) — तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत)। युग्म 3 गलत (सही: एक्स-ला-शैपल की संधि (1748 ई.) — प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी)।"},
  {"q":"[UPSC Prelims पैटर्न — मध्यकालीन ग्रंथ एवं लेखक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. किताब-ए-नवरस : इब्राहिम आदिल शाह द्वितीय (बीजापुर)\n2. तबकात-ए-नासिरी : जियाउद्दीन बरनी\n3. फतवा-ए-जहाँदारी : खाफी खाँ (मुहम्मद हाशिम)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (दक्कनी उदार सुल्तान इब्राहिम आदिल शाह II ('जगतगुरु') ने सरस्वती व गणेश वंदना सहित किताब-ए-नवरस लिखा।) युग्म 2 गलत (सही: तबकात-ए-नासिरी — मिनहाज-उस-सिराज)। युग्म 3 गलत (सही: फतवा-ए-जहाँदारी — जियाउद्दीन बरनी)।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) : प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली\n2. पिट्स इंडिया एक्ट, 1784 : कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण\n3. चार्टर अधिनियम, 1813 : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (1919 के भारत शासन अधिनियम (मोंटफोर्ड सुधार) ने महिलाओं को मताधिकार व भारत हेतु उच्चायुक्त पद भी सृजित किया।) युग्म 2 सही (1784 के पिट्स इंडिया एक्ट ने पहली बार भारत में कंपनी के क्षेत्रों को 'ब्रिटिश आधिपत्य का क्षेत्र' कहा।) युग्म 3 सही (1813 के चार्टर एक्ट से यूरोपीय व्यापारियों व ईसाई मिशनरियों को भारत आने की अनुमति मिली।)।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. भारत शासन अधिनियम, 1858 : कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद\n2. चार्टर अधिनियम, 1853 : कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण\n3. पिट्स इंडिया एक्ट, 1784 : संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (1858 के अधिनियम को शिक्षित भारतीयों ने 'अधिकारों का मैग्ना कार्टा' (महारानी विक्टोरिया घोषणा पत्र) कहा।) युग्म 2 गलत (सही: चार्टर अधिनियम, 1853 — केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता)। युग्म 3 गलत (सही: पिट्स इंडिया एक्ट, 1784 — कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण)।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों पर विचार कीजिए:\n1. एक्स-ला-शैपल की संधि (1748 ई.) : प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी\n2. इलाहाबाद की संधियाँ (1765 ई.) : ईस्ट इंडिया कंपनी को बंगाल, बिहार और उड़ीसा की दीवानी अधिकार प्राप्ति\n3. गांधी-इरविन समझौता (1931 ई.) : द्वितीय आंग्ल-मैसूर युद्ध का अंत (टीपू सुल्तान व लॉर्ड मैकार्टनी के बीच)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (यूरोप के ऑस्ट्रिया उत्तराधिकार युद्ध की समाप्ति पर हुई एक्स-ला-शैपल संधि (1748) से प्रथम कर्नाटक युद्ध रुका।) युग्म 2 सही (बक्सर युद्ध के बाद इलाहाबाद की संधि से मुगल सम्राट ने कंपनी को बंगाल-बिहार-उड़ीसा की दीवानी दी।) युग्म 3 गलत (सही: गांधी-इरविन समझौता (1931 ई.) — सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी)।"},
  {"q":"[UPSC Prelims पैटर्न — षड्दर्शन एवं प्रवर्तक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. पूर्व मीमांसा : महर्षि पतंजलि\n2. योग दर्शन : महर्षि कपिल\n3. सांख्य दर्शन : महर्षि गौतम (अक्षपाद)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: पूर्व मीमांसा — महर्षि जैमिनी)। युग्म 2 गलत (सही: योग दर्शन — महर्षि पतंजलि)। युग्म 3 गलत (सही: सांख्य दर्शन — महर्षि कपिल)।"},
  {"q":"[UPSC Prelims पैटर्न — शास्त्रीय नृत्य एवं राज्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. कुचिपुड़ी नृत्य : तमिलनाडु\n2. भरतनाट्यम : ओडिशा\n3. ओडिसी नृत्य : केरल (लास्य शैली)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: कुचिपुड़ी नृत्य — आंध्र प्रदेश)। युग्म 2 गलत (सही: भरतनाट्यम — तमिलनाडु)। युग्म 3 गलत (सही: ओडिसी नृत्य — ओडिशा)।"},
  {"q":"[UPSC Prelims पैटर्न — क्रांतिकारी घटनाएँ एवं नायक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. कर्जन वायली वध (लंदन, 1909) : मदनलाल धींगरा\n2. माइकल ओ डायर वध (1940) : भगत सिंह एवं बटुकेश्वर दत्त\n3. केंद्रीय असेंबली बम कांड (1929) : बीना दास\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (इंडिया हाउस से जुड़े मदनलाल धींगरा ने 1 जुलाई 1909 को लंदन में कर्जन वायली को गोली मारी।) युग्म 2 गलत (सही: माइकल ओ डायर वध (1940) — सरदार उधम सिंह)। युग्म 3 गलत (सही: केंद्रीय असेंबली बम कांड (1929) — भगत सिंह एवं बटुकेश्वर दत्त)।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. पिट्स इंडिया एक्ट, 1784 : कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण\n2. भारतीय परिषद अधिनियम, 1909 : मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य\n3. भारतीय परिषद अधिनियम, 1892 : अप्रत्यक्ष निर्वाचन प्रणाली का सूत्रपात एवं बजट पर बहस व प्रश्न पूछने का सीमित अधिकार\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (1784 के पिट्स इंडिया एक्ट ने पहली बार भारत में कंपनी के क्षेत्रों को 'ब्रिटिश आधिपत्य का क्षेत्र' कहा।) युग्म 2 सही (1909 के मॉर्ले-मिंटो सुधार ने फूट डालो और राज करो की नीति को संवैधानिक रूप दिया (मिंटो को साम्प्रदायिक निर्वाचन का जनक कहा गया)।) युग्म 3 सही (1892 के अधिनियम में 'निर्वाचन' शब्द नहीं था, किंतु जिला बोर्ड/विश्वविद्यालयों द्वारा परोक्ष चुनाव प्रणाली आरंभ हुई।)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — कांग्रेस अधिवेशन एवं अध्यक्ष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. 1887 मद्रास अधिवेशन   |   1. पं. जवाहरलाल नेहरू\nB. 1929 लाहौर अधिवेशन   |   2. डॉ. एनी बेसेंट (प्रथम महिला अध्यक्ष)\nC. 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष)   |   3. बदरुद्दीन तैयबजी (प्रथम मुस्लिम अध्यक्ष)\nD. 1917 कलकत्ता अधिवेशन   |   4. आचार्य जे.बी. कृपलानी","options":["A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4","A-1, B-3, C-4, D-2"],"correct":1,"explanation":"सही सुमेलन: 1887 मद्रास अधिवेशन (बदरुद्दीन तैयबजी (प्रथम मुस्लिम अध्यक्ष)), 1929 लाहौर अधिवेशन (पं. जवाहरलाल नेहरू), 1946 मेरठ अधिवेशन (स्वतंत्रता समय अध्यक्ष) (आचार्य जे.बी. कृपलानी), 1917 कलकत्ता अधिवेशन (डॉ. एनी बेसेंट (प्रथम महिला अध्यक्ष))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — सल्तनत विभाग एवं सुल्तान] सूची-I को सूची-II से सुमेलित कीजिए:\nA. दीवान-ए-खैरात   |   1. बकाया राजस्व वसूली व भ्रष्ट अधिकारियों की जाँच (अलाउद्दीन)\nB. दीवान-ए-बंदगान   |   2. असहायों व गरीब कन्याओं की सहायता का दान विभाग (फिरोज तुगलक)\nC. दीवान-ए-मुस्तखराज   |   3. कृषि विभाग व तकावी ऋण वितरण (मुहम्मद बिन तुगलक)\nD. दीवान-ए-अमीर कोही   |   4. शाही दास विभाग (फिरोजशाह तुगलक)","options":["A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3"],"correct":2,"explanation":"सही सुमेलन: दीवान-ए-खैरात (असहायों व गरीब कन्याओं की सहायता का दान विभाग (फिरोज तुगलक)), दीवान-ए-बंदगान (शाही दास विभाग (फिरोजशाह तुगलक)), दीवान-ए-मुस्तखराज (बकाया राजस्व वसूली व भ्रष्ट अधिकारियों की जाँच (अलाउद्दीन)), दीवान-ए-अमीर कोही (कृषि विभाग व तकावी ऋण वितरण (मुहम्मद बिन तुगलक))।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लॉर्ड डलहौजी (1848-56) : व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)\n2. लॉर्ड विलियम बेंटिंक (1828-35) : सती प्रथा निषेध (1829), ठगी दमन व अंग्रेजी शिक्षा पर मैकाले प्रस्ताव (1835)\n3. लॉर्ड कर्जन (1899-1905) : बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (लॉर्ड डलहौजी ने 1854 में डाकघर अधिनियम, भारतीय रेल (1853) व सिविल सेवा की खुली प्रतियोगिता लागू की।) युग्म 2 सही (राजाराम मोहन राय के सहयोग से लॉर्ड विलियम बेंटिंक ने 1829 में सती प्रथा अवैध घोषित की।) युग्म 3 सही (लॉर्ड कर्जन ने प्रशासन में केंद्रीकरण बढ़ाया, हालांकि प्राचीन स्मारक संरक्षण (1904) भी इन्हीं की देन थी।)।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. चार्ल्स मेटकाफ (1835-36) : 1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना\n2. लॉर्ड डलहौजी (1848-56) : व्यपगत सिद्धांत (सतारा-झाँसी-नागपुर), कुशासन पर अवध विलय व वुड्स डिस्पैच (1854)\n3. लॉर्ड कैनिंग (1856-62) : द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (कार्यवाहक गवर्नर-जनरल चार्ल्स मेटकाफ ने 1835 में प्रेस पर कठोर प्रतिबंध हटाए।) युग्म 2 सही (लॉर्ड डलहौजी ने 1854 में डाकघर अधिनियम, भारतीय रेल (1853) व सिविल सेवा की खुली प्रतियोगिता लागू की।) युग्म 3 गलत (सही: लॉर्ड कैनिंग (1856-62) — 1858 में क्राउन शासन की घोषणा, व्यपगत नीति वापसी एवं 1861 का उच्च न्यायालय अधिनियम)।"},
  {"q":"[UPSC Prelims पैटर्न — मध्यकालीन स्थापत्य एवं निर्माता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. अलाई दरवाजा (1311 ई.) : अलाउद्दीन खिलजी\n2. अटाला मस्जिद (जौनपुर) : इब्राहिम शाह शर्की ('पूर्व का सिराज')\n3. एत्मादुद्दौला का मकबरा (आगरा) : नूरजहाँ (जहाँगीर काल, 1626)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (अलाउद्दीन खिलजी ने कुव्वत-उल-इस्लाम मस्जिद के प्रवेश द्वार के रूप में अलाई दरवाजा बनवाया।) युग्म 2 सही (1408 ई. में इब्राहिम शाह शर्की द्वारा निर्मित अटाला मस्जिद में विशाल ढलवाँ पिश्तक व जौनपुर की विशिष्ट शैली है।) युग्म 3 सही (नूरजहाँ ने अपने पिता मिर्जा गियास बेग की स्मृति में यमुना तट पर एत्मादुद्दौला का मकबरा बनवाया।)।"},
  {"q":"[UPSC Prelims पैटर्न — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. डोमिंगो पायस (पुर्तगाल) : कृष्णदेवराय (विजयनगर, ~1520 ई.)\n2. इब्नबतूता (मोरक्को) : मुहम्मद बिन तुगलक (1333 ई.)\n3. अफनासी निकितिन (रूस) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (डोमिंगो पायस ने तुलुव वंश के कृष्णदेवराय के व्यक्तित्व व महानवमी उत्सव का सुंदर चित्रण किया।) युग्म 2 सही (मुहम्मद बिन तुगलक ने इब्नबतूता को दिल्ली का काजी नियुक्त किया और 1342 में चीन राजदूत भेजा।) युग्म 3 सही (निकितिन ने बीदर केंद्रित बहमनी सल्तनत में आम जनता की गरीबी व अमीरों की विलासिता का वर्णन किया।)।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. वेल्थ ऑफ नेशंस (1776) : एडम स्मिथ\n2. यंग इटली (1831) : ज्यूसेपे मैजिनी\n3. बोस्टन टी पार्टी (1773) : व्लादिमीर इलिच लेनिन\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (एडम स्मिथ ने मुक्त बाजार व्यापार और वाणिज्यवाद के विरोध का सिद्धांत प्रस्तुत किया।) युग्म 2 सही (मैजिनी ने मार्से में 'यंग इटली' की स्थापना कर युवाओं में लोकतांत्रिक राष्ट्रवाद जगाया।) युग्म 3 गलत (सही: बोस्टन टी पार्टी (1773) — सैमुअल एडम्स (अमेरिकी क्रांति))।"},
  {"q":"[UPSC Prelims पैटर्न — कला, गुफाएँ एवं चित्रशैली] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बनी-ठनी (मोरध्वज निहालचंद) : किशनगढ़ चित्रकला शैली (राजस्थान)\n2. सप्त पगोडा (पंच रथ) व गंगावतरण : महाबलीपुरम / मामल्लपुरम (तमिलनाडु, पल्लव)\n3. त्रिमूर्ति (महेशमूर्ति) : एलिफेंटा गुफाएँ (धारापुरी, मुंबई)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (राजा सावंत सिंह (नागरीदास) के आश्रय में चित्रकार निहालचंद ने किशनगढ़ शैली में बनी-ठनी चित्रित की।) युग्म 2 सही (पल्लव नरेश नरसिंहवर्मन प्रथम 'मामल्ल' द्वारा निर्मित महाबलीपुरम में एकाश्म रथ व तटीय मंदिर हैं।) युग्म 3 सही (मुंबई के पास धारापुरी द्वीप की एलिफेंटा गुफाओं (कल्चुरी/राष्ट्रकूट संरक्षण) में विश्वविख्यात त्रिमूर्ति शिव स्थापित हैं।)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — प्राचीन राजवंश एवं संस्थापक] सूची-I को सूची-II से सुमेलित कीजिए:\nA. सातवाहन वंश   |   1. पुलकेशिन प्रथम (जयसिंह के वंशज)\nB. बादामी के चालुक्य   |   2. सिंहविष्णु (छठी शती ई.)\nC. हर्यक वंश   |   3. सिमुक (राजधानी: प्रतिष्ठान/पैठण)\nD. कांची के पल्लव   |   4. बिम्बिसार (राजधानी: राजगृह)","options":["A-3, B-4, C-1, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2"],"correct":3,"explanation":"सही सुमेलन: सातवाहन वंश (सिमुक (राजधानी: प्रतिष्ठान/पैठण)), बादामी के चालुक्य (पुलकेशिन प्रथम (जयसिंह के वंशज)), हर्यक वंश (बिम्बिसार (राजधानी: राजगृह)), कांची के पल्लव (सिंहविष्णु (छठी शती ई.))।"},
  {"q":"[UPSC Prelims पैटर्न — वैदिक शब्दावली एवं उपनिषद] निम्नलिखित युग्मों पर विचार कीजिए:\n1. संगृहीता : कोषाध्यक्ष\n2. तत्त्वमसि संवाद (उद्दालक-श्वेतकेतु) : गाय (न मारे जाने योग्य)\n3. अघन्या : बृहदारण्यक उपनिषद\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (उत्तर-वैदिक काल में 'संगृहीता' शाही कोषाध्यक्ष होता था।) युग्म 2 गलत (सही: तत्त्वमसि संवाद (उद्दालक-श्वेतकेतु) — छान्दोग्य उपनिषद)। युग्म 3 गलत (सही: अघन्या — गाय (न मारे जाने योग्य))।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बसीन की संधि (1802 ई.) : पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना\n2. पूना समझौता / पूना पैक्ट (1932 ई.) : प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति)\n3. सालबाई की संधि (1782 ई.) : महाराजा रणजीत सिंह और लॉर्ड मिंटो प्रथम (चार्ल्स मेटकाफ) — सतलज नदी सीमा तय\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (1802 की बसीन संधि के अंतर्गत पेशवा बाजीराव द्वितीय ने कंपनी की सहायक सेना व पूना में ब्रिटिश संरक्षण स्वीकार किया।) युग्म 2 गलत (सही: पूना समझौता / पूना पैक्ट (1932 ई.) — दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147))। युग्म 3 गलत (सही: सालबाई की संधि (1782 ई.) — प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — गुप्तकालीन विज्ञान, साहित्य व प्रशासन] सूची-I को सूची-II से सुमेलित कीजिए:\nA. मृच्छकटिकम् (मिट्टी की गाड़ी)   |   1. शून्य-दशमलव प्रणाली, π का सटीक मान तथा सूर्य-चंद्र ग्रहण का वैज्ञानिक कारण\nB. आर्यभट्ट (कुसुमपुर / पाटलिपुत्र)   |   2. भूमि अभिलेखों की सुरक्षा एवं स्वामित्व जांच करने वाला अधिकारी\nC. प्रयाग प्रशस्ति   |   3. शूद्रक (सामान्य नागरिकों व राजनीतिक उथल-पुथल का यथार्थवादी नाटक)\nD. पुस्तपाल (गुप्त प्रशासन)   |   4. हरिषेण (समुद्रगुप्त के संधिविग्रहिक व महादंडनायक)","options":["A-3, B-1, C-2, D-4","A-3, B-4, C-1, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-4, D-2"],"correct":3,"explanation":"सही सुमेलन: मृच्छकटिकम् (मिट्टी की गाड़ी) (शूद्रक (सामान्य नागरिकों व राजनीतिक उथल-पुथल का यथार्थवादी नाटक)), आर्यभट्ट (कुसुमपुर / पाटलिपुत्र) (शून्य-दशमलव प्रणाली, π का सटीक मान तथा सूर्य-चंद्र ग्रहण का वैज्ञानिक कारण), प्रयाग प्रशस्ति (हरिषेण (समुद्रगुप्त के संधिविग्रहिक व महादंडनायक)), पुस्तपाल (गुप्त प्रशासन) (भूमि अभिलेखों की सुरक्षा एवं स्वामित्व जांच करने वाला अधिकारी)।"},
  {"q":"[UPSC Prelims पैटर्न — मध्यकालीन स्थापत्य एवं निर्माता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बीबी का मकबरा (औरंगाबाद) : औरंगजेब (पुत्र आजम शाह द्वारा रबिया-उद-दुर्रानी हेतु)\n2. सासाराम झील मकबरा : शेरशाह सूरी\n3. एत्मादुद्दौला का मकबरा (आगरा) : भारत में दोहरे गुंबद का प्रारंभिक पूर्ण प्रयोग (लोदी गार्डन)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (औरंगजेब की पत्नी दिलरास बानो बेगम की स्मृति में 1651-61/78 के दौरान बीबी का मकबरा बना।) युग्म 2 सही (बिहार के सासाराम में कृत्रिम झील के बीच ऊँचे चबूतरे पर निर्मित शेरशाह का मकबरा अफगान कला का शिखर है।) युग्म 3 गलत (सही: एत्मादुद्दौला का मकबरा (आगरा) — नूरजहाँ (जहाँगीर काल, 1626))।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों पर विचार कीजिए:\n1. तालीकोटा का युद्ध (1565 ई.) : अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया\n2. पानीपत का द्वितीय युद्ध (1556 ई.) : मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया\n3. चंदावर का युद्ध (1194 ई.) : बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: तालीकोटा का युद्ध (1565 ई.) — दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया)। युग्म 2 गलत (सही: पानीपत का द्वितीय युद्ध (1556 ई.) — अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया)। युग्म 3 गलत (सही: चंदावर का युद्ध (1194 ई.) — मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया)।"},
  {"q":"[UPSC Prelims पैटर्न — सुधार संगठन एवं संस्थापक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. प्रार्थना समाज (1867) : आत्माराम पांडुरंग (केशव चंद्र सेन प्रेरणा)\n2. SNDP योगम (1903) : श्री नारायण गुरु\n3. सत्यशोधक समाज (1873) : राजा राममोहन राय\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (1867 में आत्माराम पांडुरंग द्वारा स्थापित प्रार्थना समाज को एम.जी. रानाडे व आर.जी. भंडारकर ने गति दी।) युग्म 2 सही (एझावा समुदाय व सभी दलितों के उत्थान हेतु श्री नारायण गुरु ने केरल में SNDP स्थापित किया।) युग्म 3 गलत (सही: सत्यशोधक समाज (1873) — ज्योतिबा फुले)।"},
  {"q":"[UPSC Prelims पैटर्न — प्राचीन प्रशासनिक अधिकारी] निम्नलिखित युग्मों पर विचार कीजिए:\n1. समाहर्ता : राजकीय कोषागार एवं अन्नागार का प्रमुख (मौर्यकाल)\n2. सन्निधाता : माप-तौल एवं बाट मानक नियंत्रण अधिकारी\n3. पौतवाध्यक्ष : विदेश नीति एवं युद्ध-संधि मामलों का मंत्री (गुप्तकाल)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: समाहर्ता — राजस्व संग्रह एवं बजट का सर्वोच्च अधिकारी (मौर्यकाल))। युग्म 2 गलत (सही: सन्निधाता — राजकीय कोषागार एवं अन्नागार का प्रमुख (मौर्यकाल))। युग्म 3 गलत (सही: पौतवाध्यक्ष — माप-तौल एवं बाट मानक नियंत्रण अधिकारी)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — प्रमुख संधियाँ एवं समझौते] सूची-I को सूची-II से सुमेलित कीजिए:\nA. पूना समझौता / पूना पैक्ट (1932 ई.)   |   1. प्रथम आंग्ल-मैसूर युद्ध की समाप्ति (विजित क्षेत्रों की वापसी व पारस्परिक रक्षा समझौता)\nB. मद्रास की संधि (1769 ई.)   |   2. तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत\nC. सुगौली की संधि (1816 ई.)   |   3. दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)\nD. पेरिस की संधि (1763 ई.)   |   4. आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)","options":["A-1, B-3, C-4, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4"],"correct":1,"explanation":"सही सुमेलन: पूना समझौता / पूना पैक्ट (1932 ई.) (दलितों के लिए पृथक निर्वाचक मंडल के स्थान पर संयुक्त निर्वाचन में आरक्षित सीटें (71 से 147)), मद्रास की संधि (1769 ई.) (प्रथम आंग्ल-मैसूर युद्ध की समाप्ति (विजित क्षेत्रों की वापसी व पारस्परिक रक्षा समझौता)), सुगौली की संधि (1816 ई.) (आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)), पेरिस की संधि (1763 ई.) (तृतीय आंग्ल-फ्रांसीसी कर्नाटक युद्ध की समाप्ति व भारत में फ्रांसीसी राजनीतिक शक्ति का अंत)।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों पर विचार कीजिए:\n1. तक्कोलम का युद्ध (949 ई.) : राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया\n2. तालीकोटा का युद्ध (1565 ई.) : दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया\n3. हाइडेस्पीज का युद्ध (326 ई.पू.) : सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (तक्कोलम के युद्ध में राष्ट्रकूट राजा कृष्ण तृतीय ने चोलों को करारी हार दी।) युग्म 2 सही (1565 के तालीकोटा युद्ध में बीजापुर, गोलकुंडा, अहमदनगर व बीदर की संयुक्त सेना ने विजयनगर साम्राज्य को ध्वस्त किया।) युग्म 3 सही (326 ई.पू. में वितस्ता नदी तट पर सिकंदर ने पोरस को हराया किंतु उनकी वीरता से प्रभावित होकर राज्य लौटाया।)।"},
  {"q":"[UPSC Prelims पैटर्न — सिन्धु स्थल एवं नदी] निम्नलिखित युग्मों पर विचार कीजिए:\n1. मोहनजोदड़ो : भादर नदी\n2. रंगपुर : दाश्क नदी\n3. सुत्कागेंडोर : चिनाब नदी\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: मोहनजोदड़ो — सिन्धु नदी)। युग्म 2 गलत (सही: रंगपुर — भादर नदी)। युग्म 3 गलत (सही: सुत्कागेंडोर — दाश्क नदी)।"},
  {"q":"[UPSC Prelims पैटर्न — जनजातीय-किसान विद्रोह एवं नेतृत्व] निम्नलिखित युग्मों पर विचार कीजिए:\n1. दक्कन उपद्रव (1875) परिणाम : दक्कन कृषक राहत अधिनियम, 1879\n2. रम्पा विद्रोह (1922-24) : बुद्धो भगत (सिंदराय व बिंद्राय सहयोगी)\n3. कोल विद्रोह (1831-32) : जतरा भगत (जतरा उराँव)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (मारवाड़ी व गुजराती साहूकारों की ऋण बहियाँ जलाए जाने के बाद 1879 का राहत कानून बना।) युग्म 2 गलत (सही: रम्पा विद्रोह (1922-24) — अल्लूरी सीताराम राजू)। युग्म 3 गलत (सही: कोल विद्रोह (1831-32) — बुद्धो भगत (सिंदराय व बिंद्राय सहयोगी))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — प्रमुख संधियाँ एवं समझौते] सूची-I को सूची-II से सुमेलित कीजिए:\nA. मंगलौर की संधि (1784 ई.)   |   1. पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना\nB. एक्स-ला-शैपल की संधि (1748 ई.)   |   2. प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति)\nC. सालबाई की संधि (1782 ई.)   |   3. द्वितीय आंग्ल-मैसूर युद्ध का अंत (टीपू सुल्तान व लॉर्ड मैकार्टनी के बीच)\nD. बसीन की संधि (1802 ई.)   |   4. प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी","options":["A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1","A-4, B-3, C-2, D-1"],"correct":1,"explanation":"सही सुमेलन: मंगलौर की संधि (1784 ई.) (द्वितीय आंग्ल-मैसूर युद्ध का अंत (टीपू सुल्तान व लॉर्ड मैकार्टनी के बीच)), एक्स-ला-शैपल की संधि (1748 ई.) (प्रथम आंग्ल-फ्रांसीसी कर्नाटक युद्ध का अंत व मद्रास की अंग्रेजों को वापसी), सालबाई की संधि (1782 ई.) (प्रथम आंग्ल-मराठा युद्ध की समाप्ति (माधवराव नारायण को पेशवा स्वीकृति)), बसीन की संधि (1802 ई.) (पेशवा बाजीराव द्वितीय द्वारा अंग्रेजों की सहायक संधि स्वीकार करना)।"},
  {"q":"[UPSC Prelims पैटर्न — संवैधानिक अधिनियम एवं प्रावधान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. भारत शासन अधिनियम, 1858 : कंपनी से ब्रिटिश क्राउन को सत्ता हस्तांतरण, गवर्नर-जनरल का 'वायसराय' बनना व भारत सचिव पद\n2. चार्टर अधिनियम, 1833 : संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\n3. चार्टर अधिनियम, 1853 : भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (1858 के अधिनियम को शिक्षित भारतीयों ने 'अधिकारों का मैग्ना कार्टा' (महारानी विक्टोरिया घोषणा पत्र) कहा।) युग्म 2 सही (1833 के चार्टर एक्ट से लॉर्ड विलियम बेंटिंक भारत के प्रथम गवर्नर-जनरल बने।) युग्म 3 गलत (सही: चार्टर अधिनियम, 1853 — केंद्रीय विधान परिषद (Mini Parliament) का गठन व सिविल सेवा के लिए खुली प्रतियोगिता)।"},
  {"q":"[UPSC Prelims पैटर्न — सिन्धु स्थल एवं नदी] निम्नलिखित युग्मों पर विचार कीजिए:\n1. दैमाबाद : प्रवरा नदी\n2. हड़प्पा : रावी नदी\n3. लोथल : सतलज नदी\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (दैमाबाद महाराष्ट्र में गोदावरी की सहायक प्रवरा नदी के तट पर स्थित था।) युग्म 2 सही (हड़प्पा पुरास्थल रावी नदी के बाएँ तट पर स्थित था।) युग्म 3 गलत (सही: लोथल — भोगवा नदी)।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. आराम हराम है / 'Who lives if India dies?' : पं. जवाहरलाल नेहरू\n2. स्वराज मेरा जन्मसिद्ध अधिकार है : स्वामी दयानंद सरस्वती\n3. वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग : लाला लाजपत राय (साइमन कमीशन विरोध)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (जवाहरलाल नेहरू ने लाहौर अधिवेशन (1929) में पूर्ण स्वराज व स्वतंत्रता संग्राम में 'आराम हराम है' नारा दिया।) युग्म 2 गलत (सही: स्वराज मेरा जन्मसिद्ध अधिकार है — बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916))। युग्म 3 गलत (सही: वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग — स्वामी दयानंद सरस्वती)।"},
  {"q":"[UPSC Prelims पैटर्न — प्राचीन ग्रंथ एवं रचयिता] निम्नलिखित युग्मों पर विचार कीजिए:\n1. स्वप्नवासवदत्तम् : भास\n2. वृहत्संहिता : वराहमिहिर\n3. शिलप्पादिकारम् : इलंगो आदिगल\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (संस्कृत नाटककार भास ने वत्सराज उदयन और वासवदत्ता पर आधारित 'स्वप्नवासवदत्तम्' लिखा।) युग्म 2 सही (चंद्रगुप्त II के नवरत्न वराहमिहिर ने 'वृहत्संहिता' (विश्वकोश) व 'बृहज्जातक' लिखे।) युग्म 3 सही (चेर राजकुमार व जैन मुनि इलंगो आदिगल ने संगम युग में 'शिलप्पादिकारम्' लिखा।)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — सल्तनत विभाग एवं सुल्तान] सूची-I को सूची-II से सुमेलित कीजिए:\nA. दीवान-ए-अर्ज   |   1. धार्मिक मामले, वजीफे व राजनयिक/विदेश पत्राचार\nB. दीवान-ए-अमीर कोही   |   2. वित्त एवं राजस्व मंत्रालय (प्रमुख: वजीर)\nC. दीवान-ए-विजारत   |   3. सैन्य विभाग (स्थापना: बलबन)\nD. दीवान-ए-रिसालत   |   4. कृषि विभाग व तकावी ऋण वितरण (मुहम्मद बिन तुगलक)","options":["A-4, B-3, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-1, D-2","A-3, B-4, C-2, D-1"],"correct":3,"explanation":"सही सुमेलन: दीवान-ए-अर्ज (सैन्य विभाग (स्थापना: बलबन)), दीवान-ए-अमीर कोही (कृषि विभाग व तकावी ऋण वितरण (मुहम्मद बिन तुगलक)), दीवान-ए-विजारत (वित्त एवं राजस्व मंत्रालय (प्रमुख: वजीर)), दीवान-ए-रिसालत (धार्मिक मामले, वजीफे व राजनयिक/विदेश पत्राचार)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — शास्त्रीय संगीत एवं वाद्ययंत्र] सूची-I को सूची-II से सुमेलित कीजिए:\nA. पंडित शिवकुमार शर्मा   |   1. बांसुरी (सुषिर वाद्य)\nB. पंडित रविशंकर   |   2. शहनाई\nC. उस्ताद बिस्मिल्लाह खाँ   |   3. संतूर (कश्मीर का 100-तार वाद्य)\nD. पं. हरिप्रसाद चौरसिया   |   4. मैहर घराना (सितार)","options":["A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2"],"correct":0,"explanation":"सही सुमेलन: पंडित शिवकुमार शर्मा (संतूर (कश्मीर का 100-तार वाद्य)), पंडित रविशंकर (मैहर घराना (सितार)), उस्ताद बिस्मिल्लाह खाँ (शहनाई), पं. हरिप्रसाद चौरसिया (बांसुरी (सुषिर वाद्य))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — संवैधानिक अधिनियम एवं प्रावधान] सूची-I को सूची-II से सुमेलित कीजिए:\nA. भारत शासन अधिनियम, 1935   |   1. मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य\nB. चार्टर अधिनियम, 1813   |   2. अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण\nC. भारतीय परिषद अधिनियम, 1909   |   3. कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण\nD. पिट्स इंडिया एक्ट, 1784   |   4. भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष","options":["A-2, B-1, C-4, D-3","A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3"],"correct":2,"explanation":"सही सुमेलन: भारत शासन अधिनियम, 1935 (अखिल भारतीय संघ प्रावधान, शक्तियों की 3 सूचियाँ, आरबीआई व बर्मा का भारत से पृथक्करण), चार्टर अधिनियम, 1813 (भारतीय व्यापार एकाधिकार अंत (चाय-चीन अपवाद), ईसाई मिशनरी प्रवेश व शिक्षा हेतु ₹1 लाख प्रतिवर्ष), भारतीय परिषद अधिनियम, 1909 (मुस्लिम समुदाय हेतु पृथक निर्वाचन, बजट पर संकल्प-अनुपूरक प्रश्न व सत्येंद्र प्रसाद सिन्हा विधि सदस्य), पिट्स इंडिया एक्ट, 1784 (कंपनी के व्यापारिक (Court of Directors) व राजनीतिक (Board of Control) कार्यों में द्वैध नियंत्रण)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — सिन्धु स्थल एवं नदी] सूची-I को सूची-II से सुमेलित कीजिए:\nA. मोहनजोदड़ो   |   1. भादर नदी\nB. रंगपुर   |   2. हिंडन नदी\nC. रोपड़   |   3. सिन्धु नदी\nD. आलमगीरपुर   |   4. सतलज नदी","options":["A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2"],"correct":3,"explanation":"सही सुमेलन: मोहनजोदड़ो (सिन्धु नदी), रंगपुर (भादर नदी), रोपड़ (सतलज नदी), आलमगीरपुर (हिंडन नदी)।"},
  {"q":"[UPSC Prelims पैटर्न — दक्कनी सल्तनत व राजवंश] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बरार (इमादशाही) व बीदर (बरीदशाही) : फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद\n2. बीजापुर (आदिलशाही, 1489) : युसुफ आदिल शाह\n3. अहमदनगर (निजामशाही, 1490) : कुली कुतुब शाह\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (बरार सबसे पहले 1484-90 में अलग हुआ व 1574 में अहमदनगर में विलीन हुआ; बीदर सबसे अंत में अलग हुआ।) युग्म 2 सही (युसुफ आदिल शाह ने 1489 में स्वतंत्र बीजापुर राज्य बनाया जहाँ बाद में गोल गुंबज बना।) युग्म 3 गलत (सही: अहमदनगर (निजामशाही, 1490) — मलिक अहमद)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — प्राचीन ग्रंथ एवं रचयिता] सूची-I को सूची-II से सुमेलित कीजिए:\nA. तिरुक्कुरल   |   1. दण्डी\nB. दशकुमारचरितम्   |   2. विशाखदत्त\nC. महाभाष्य   |   3. तिरुवल्लुवर\nD. मुद्राराक्षस   |   4. पतंजलि","options":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4"],"correct":0,"explanation":"सही सुमेलन: तिरुक्कुरल (तिरुवल्लुवर), दशकुमारचरितम् (दण्डी), महाभाष्य (पतंजलि), मुद्राराक्षस (विशाखदत्त)।"},
  {"q":"[UPSC Prelims पैटर्न — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. सातवाहन वंश : बिम्बिसार (राजधानी: राजगृह)\n2. हर्यक वंश : सिंहविष्णु (छठी शती ई.)\n3. कांची के पल्लव : गोपाल (लगभग 750 ई.)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: सातवाहन वंश — सिमुक (राजधानी: प्रतिष्ठान/पैठण))। युग्म 2 गलत (सही: हर्यक वंश — बिम्बिसार (राजधानी: राजगृह))। युग्म 3 गलत (सही: कांची के पल्लव — सिंहविष्णु (छठी शती ई.))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — जनजातीय-किसान विद्रोह एवं नेतृत्व] सूची-I को सूची-II से सुमेलित कीजिए:\nA. ताना भगत आंदोलन (1914)   |   1. दक्कन कृषक राहत अधिनियम, 1879\nB. दक्कन उपद्रव (1875) परिणाम   |   2. बख्शी जगबंधु विद्याधर\nC. रम्पा विद्रोह (1922-24)   |   3. जतरा भगत (जतरा उराँव)\nD. पाइक विद्रोह (ओडिशा, 1817)   |   4. अल्लूरी सीताराम राजू","options":["A-3, B-4, C-1, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4"],"correct":2,"explanation":"सही सुमेलन: ताना भगत आंदोलन (1914) (जतरा भगत (जतरा उराँव)), दक्कन उपद्रव (1875) परिणाम (दक्कन कृषक राहत अधिनियम, 1879), रम्पा विद्रोह (1922-24) (अल्लूरी सीताराम राजू), पाइक विद्रोह (ओडिशा, 1817) (बख्शी जगबंधु विद्याधर)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — सिन्धु सभ्यता के साक्ष्य] सूची-I को सूची-II से सुमेलित कीजिए:\nA. तांबवती नाम से प्रसिद्ध ताम्रपाषाण स्थल   |   1. चन्हूदड़ो\nB. लिपस्टिक व बिना दुर्ग का औद्योगिक नगर   |   2. मोहनजोदड़ो\nC. शैलकृत जल जलाशय व साइनबोर्ड   |   3. आहार (राजस्थान)\nD. कांस्य की नर्तकी   |   4. धौलावीरा","options":["A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-4, C-1, D-2"],"correct":0,"explanation":"सही सुमेलन: तांबवती नाम से प्रसिद्ध ताम्रपाषाण स्थल (आहार (राजस्थान)), लिपस्टिक व बिना दुर्ग का औद्योगिक नगर (चन्हूदड़ो), शैलकृत जल जलाशय व साइनबोर्ड (धौलावीरा), कांस्य की नर्तकी (मोहनजोदड़ो)।"},
  {"q":"[UPSC Prelims पैटर्न — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. राष्ट्रकूट वंश : दंतिदुर्ग (752 ई.)\n2. गुप्त वंश : श्रीगुप्त (तीसरी शती ई.)\n3. हर्यक वंश : बिम्बिसार (राजधानी: राजगृह)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (दंतिदुर्ग ने बादामी के अंतिम चालुक्य शासक कीर्तिवर्मन II को हराकर राष्ट्रकूट वंश स्थापित किया।) युग्म 2 सही (प्रयाग प्रशस्ति व पूना ताम्रपत्र के अनुसार श्रीगुप्त गुप्त राजवंश के संस्थापक थे।) युग्म 3 सही (बिम्बिसार ने 544 ई.पू. में हर्यक वंश की स्थापना की थी।)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक युद्ध एवं परिणाम] सूची-I को सूची-II से सुमेलित कीजिए:\nA. करनाल का युद्ध (1739 ई.)   |   1. राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया\nB. पानीपत का द्वितीय युद्ध (1556 ई.)   |   2. नादिर शाह ने मुगल सम्राट मुहम्मद शाह 'रंगीला' की सेना को हराया\nC. तक्कोलम का युद्ध (949 ई.)   |   3. दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया\nD. तालीकोटा का युद्ध (1565 ई.)   |   4. अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया","options":["A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3","A-2, B-4, C-1, D-3"],"correct":3,"explanation":"सही सुमेलन: करनाल का युद्ध (1739 ई.) (नादिर शाह ने मुगल सम्राट मुहम्मद शाह 'रंगीला' की सेना को हराया), पानीपत का द्वितीय युद्ध (1556 ई.) (अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया), तक्कोलम का युद्ध (949 ई.) (राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया), तालीकोटा का युद्ध (1565 ई.) (दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक नारे एवं उद्घोष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा   |   1. जवाहरलाल नेहरू\nB. मेरे शरीर पर पड़ी एक-एक लाठी...   |   2. महात्मा गांधी\nC. करो या मरो (Do or Die)   |   3. सुभाष चंद्र बोस\nD. आराम हराम है / Who lives if India dies   |   4. लाला लाजपत राय","options":["A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2"],"correct":1,"explanation":"सही सुमेलन: तुम मुझे खून दो, मैं तुम्हें आज़ादी दूँगा (सुभाष चंद्र बोस), मेरे शरीर पर पड़ी एक-एक लाठी... (लाला लाजपत राय), करो या मरो (Do or Die) (महात्मा गांधी), आराम हराम है / Who lives if India dies (जवाहरलाल नेहरू)।"},
  {"q":"[UPSC Prelims पैटर्न — सिन्धु सभ्यता के साक्ष्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. शैलकृत जल जलाशय व साइनबोर्ड : धौलावीरा\n2. लिपस्टिक व बिना दुर्ग का औद्योगिक नगर : चन्हूदड़ो\n3. राख के टीले (पिकलिहल, उत्नूर) : आहार (राजस्थान)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (धौलावीरा से उत्कृष्ट पत्थर के बने विशाल जलाशय व 10 अक्षरों का साइनबोर्ड मिला।) युग्म 2 सही (चन्हूदड़ो से लिपस्टिक, वक्राकार ईंटें व मनके बनाने के कारखाने मिले।) युग्म 3 गलत (सही: राख के टीले (पिकलिहल, उत्नूर) — दक्षिण भारत (कर्नाटक-आंध्र))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विदेशी यात्री एवं शासक] सूची-I को सूची-II से सुमेलित कीजिए:\nA. सर थॉमस रो (ब्रिटेन)   |   1. देवराय द्वितीय (विजयनगर, 1443 ई.)\nB. अब्दुर रज्जाक (फारस/समरकंद)   |   2. अच्युतदेवराय (विजयनगर, ~1535 ई.)\nC. डोमिंगो पायस (पुर्तगाल)   |   3. जहाँगीर (1615-1619 ई.)\nD. फर्नओ नूनिज (पुर्तगाल)   |   4. कृष्णदेवराय (विजयनगर, ~1520 ई.)","options":["A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2"],"correct":2,"explanation":"सही सुमेलन: सर थॉमस रो (ब्रिटेन) (जहाँगीर (1615-1619 ई.)), अब्दुर रज्जाक (फारस/समरकंद) (देवराय द्वितीय (विजयनगर, 1443 ई.)), डोमिंगो पायस (पुर्तगाल) (कृष्णदेवराय (विजयनगर, ~1520 ई.)), फर्नओ नूनिज (पुर्तगाल) (अच्युतदेवराय (विजयनगर, ~1535 ई.))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — संवैधानिक अधिनियम एवं प्रावधान] सूची-I को सूची-II से सुमेलित कीजिए:\nA. भारतीय परिषद अधिनियम, 1861   |   1. गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ\nB. रेगुलेटिंग एक्ट, 1773   |   2. संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति)\nC. भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड)   |   3. मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)\nD. चार्टर अधिनियम, 1833   |   4. प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली","options":["A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4","A-1, B-3, C-4, D-2"],"correct":0,"explanation":"सही सुमेलन: भारतीय परिषद अधिनियम, 1861 (मद्रास-बंबई को विधायी शक्ति वापसी (विकेंद्रीकरण), पोर्टफोलियो प्रणाली व वायसराय अध्यादेश (6 माह)), रेगुलेटिंग एक्ट, 1773 (गवर्नर-जनरल पद सृजन, कलकत्ता सुप्रीम कोर्ट (सर एलिजा इम्पे) व कंपनी पर संसदीय नियंत्रण का आरंभ), भारत शासन अधिनियम, 1919 (मोंटेग्यू-चेम्सफोर्ड) (प्रांतों में द्वैध शासन, लोक सेवा आयोग (1926) व केंद्र में प्रत्यक्ष चुनाव-द्विसदन प्रणाली), चार्टर अधिनियम, 1833 (संपूर्ण केंद्रीकरण, प्रथम विधि आयोग (मैकाले), दास प्रथा उन्मूलन निर्देश व धारा 87 (अभेद नीति))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — कला, गुफाएँ एवं चित्रशैली] सूची-I को सूची-II से सुमेलित कीजिए:\nA. पद्मपाणि बोधिसत्त्व व मरणासन्न राजकुमारी   |   1. पहाड़ी चित्रकला शैली (हिमाचल/जम्मू)\nB. सप्त पगोडा (पंच रथ) व गंगावतरण   |   2. एलोरा गुफाएँ (महाराष्ट्र)\nC. कैलाश मंदिर (गुफा सं. 16, एकाश्म)   |   3. अजंता गुफाएँ (महाराष्ट्र, वाकाटक युग)\nD. कांगड़ा व बसोहली चित्रकला   |   4. महाबलीपुरम / मामल्लपुरम (तमिलनाडु, पल्लव)","options":["A-3, B-2, C-4, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1"],"correct":3,"explanation":"सही सुमेलन: पद्मपाणि बोधिसत्त्व व मरणासन्न राजकुमारी (अजंता गुफाएँ (महाराष्ट्र, वाकाटक युग)), सप्त पगोडा (पंच रथ) व गंगावतरण (महाबलीपुरम / मामल्लपुरम (तमिलनाडु, पल्लव)), कैलाश मंदिर (गुफा सं. 16, एकाश्म) (एलोरा गुफाएँ (महाराष्ट्र)), कांगड़ा व बसोहली चित्रकला (पहाड़ी चित्रकला शैली (हिमाचल/जम्मू))।"},
  {"q":"[UPSC Prelims पैटर्न — गवर्नर-जनरल / वायसराय एवं कार्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. लॉर्ड लिनलिथगो (1936-44) : प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन\n2. वॉरेन हेस्टिंग्स (1772-85) : द्वैध शासन की समाप्ति, 1774 में कलकत्ता सुप्रीम कोर्ट व इजारेदारी पंचशाला बंदोबस्त\n3. लॉर्ड मेयो (1869-72) : बंगाल विभाजन (16 अक्टूबर 1905), सर एंड्रयू फ्रेजर पुलिस आयोग व यंगहसबैंड तिब्बत मिशन\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (लॉर्ड लिनलिथगो ब्रिटिश भारत में सबसे लंबे समय (1936-1944) तक रहने वाले वायसराय थे।) युग्म 2 सही (वॉरेन हेस्टिंग्स बंगाल के प्रथम गवर्नर-जनरल (1773 एक्ट) बने; उन्होंने कलकत्ता मदरसा (1781) की स्थापना भी की।) युग्म 3 गलत (सही: लॉर्ड मेयो (1869-72) — 1872 की प्रथम जनगणना, राजकोट-अजमेर मेयो कॉलेज व वित्तीय विकेंद्रीकरण)।"},
  {"q":"[UPSC Prelims पैटर्न — व्यपगत सिद्धांत (विलय वर्ष)] निम्नलिखित युग्मों पर विचार कीजिए:\n1. नागपुर विलय : 1854 ई.\n2. झाँसी विलय (गंगाधर राव मृत्यु बाद) : 1853 ई.\n3. सतारा विलय (डलहौजी) : 1848 ई. (प्रथम व्यपगत राज्य)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (रघुजी तृतीय के निधन के बाद 1854 ई. में नागपुर का ब्रिटिश साम्राज्य में विलय हो गया।) युग्म 2 सही (राजा गंगाधर राव के दत्तक पुत्र दामोदर राव को अमान्य ठहराकर 1853 में झाँसी का विलय हुआ।) युग्म 3 सही (अप्पा साहेब के बाद दत्तक पुत्र को अमान्य कर 1848 में सर्वप्रथम सतारा का ब्रिटिश विलय हुआ।)।"},
  {"q":"[UPSC CDS/Prelims PYQ] भारतीय स्वतंत्रता संग्राम के दौरान निम्नलिखित घटनाओं का सही कालानुक्रम क्या है?\n1. गांधी-इरविन समझौता\n2. पूना पैक्ट\n3. भारतीय राष्ट्रीय कांग्रेस का कराची अधिवेशन\n4. भगत सिंह, राजगुरु व सुखदेव को फांसी","options":["1 - 4 - 3 - 2","1 - 4 - 2 - 3","4 - 1 - 3 - 2","1 - 3 - 4 - 2"],"correct":0,"explanation":"गांधी-इरविन समझौता (5 मार्च 1931) -> क्रांतिकारियों को फांसी (23 मार्च 1931) -> कराची अधिवेशन (26-31 मार्च 1931) -> पूना पैक्ट (24 सितंबर 1932)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — गवर्नर-जनरल / वायसराय एवं कार्य] सूची-I को सूची-II से सुमेलित कीजिए:\nA. लॉर्ड लिटन (1876-80)   |   1. बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना\nB. लॉर्ड लिनलिथगो (1936-44)   |   2. 1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना\nC. चार्ल्स मेटकाफ (1835-36)   |   3. वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट\nD. लॉर्ड कॉर्नवालिस (1786-93)   |   4. प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन","options":["A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1"],"correct":3,"explanation":"सही सुमेलन: लॉर्ड लिटन (1876-80) (वर्नाक्युलर प्रेस एक्ट (1878), सिविल सेवा आयु 21 से 19 वर्ष करना व रॉयल टाइटल्स एक्ट), लॉर्ड लिनलिथगो (1936-44) (प्रांतीय चुनाव (1937), द्वितीय विश्व युद्ध प्रवेश (1939), अगस्त प्रस्ताव (1940) व क्रिप्स मिशन), चार्ल्स मेटकाफ (1835-36) (1823 के जॉन एडम्स प्रेस लाइसेंस नियम रद्द कर प्रेस की स्वतंत्रता बहाल करना), लॉर्ड कॉर्नवालिस (1786-93) (बंगाल-बिहार में स्थायी बंदोबस्त (1793) एवं जिला कलेक्टर से न्यायिक शक्ति पृथक करना)।"},
  {"q":"[UPSC Prelims पैटर्न — अशोक के प्रमुख शिलालेख] निम्नलिखित युग्मों पर विचार कीजिए:\n1. तृतीय वृहद शिलालेख : प्रादेशिक, रज्जुक व युक्त अधिकारियों का हर 5वें वर्ष धम्म प्रचार दौरा\n2. प्रथम वृहद शिलालेख : राज्याभिषेक के 13वें वर्ष 'धम्म महामात्र' की नियुक्ति व बंदियों के कल्याण का निर्देश\n3. पाँचवाँ वृहद शिलालेख : सर्वधर्म समभाव, वाक्-संयम व विभिन्न संप्रदायों के सार की वृद्धि\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (तृतीय वृहद शिलालेख में प्रति पाँच वर्ष प्रांतीय अधिकारियों के निरीक्षण दौरे का निर्देश है।) युग्म 2 गलत (सही: प्रथम वृहद शिलालेख — पशुबलि की निंदा (राजकीय रसोई में भी केवल 2 मोर-1 हिरण की सीमा व बाद में पूर्ण बंद))। युग्म 3 गलत (सही: पाँचवाँ वृहद शिलालेख — राज्याभिषेक के 13वें वर्ष 'धम्म महामात्र' की नियुक्ति व बंदियों के कल्याण का निर्देश)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक युद्ध एवं परिणाम] सूची-I को सूची-II से सुमेलित कीजिए:\nA. नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष)   |   1. बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली\nB. खानवा का युद्ध (1527 ई.)   |   2. शेर खान (शेरशाह सूरी) ने हुमायूँ को पराजित कर 'शेरशाह' उपाधि धारण की\nC. तक्कोलम का युद्ध (949 ई.)   |   3. चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया\nD. चौसा का युद्ध (1539 ई.)   |   4. राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया","options":["A-3, B-1, C-2, D-4","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2"],"correct":2,"explanation":"सही सुमेलन: नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष) (चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया), खानवा का युद्ध (1527 ई.) (बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली), तक्कोलम का युद्ध (949 ई.) (राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया), चौसा का युद्ध (1539 ई.) (शेर खान (शेरशाह सूरी) ने हुमायूँ को पराजित कर 'शेरशाह' उपाधि धारण की)।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख संधियाँ एवं समझौते] निम्नलिखित युग्मों पर विचार कीजिए:\n1. मंगलौर की संधि (1784 ई.) : सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी\n2. गांधी-इरविन समझौता (1931 ई.) : प्रथम आंग्ल-मैसूर युद्ध की समाप्ति (विजित क्षेत्रों की वापसी व पारस्परिक रक्षा समझौता)\n3. मद्रास की संधि (1769 ई.) : आंग्ल-नेपाल (गोरखा) युद्ध की समाप्ति (गढ़वाल, कुमाऊँ व तराई ब्रिटिश भारत को मिले)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: मंगलौर की संधि (1784 ई.) — द्वितीय आंग्ल-मैसूर युद्ध का अंत (टीपू सुल्तान व लॉर्ड मैकार्टनी के बीच))। युग्म 2 गलत (सही: गांधी-इरविन समझौता (1931 ई.) — सविनय अवज्ञा आंदोलन का स्थगन और कांग्रेस की द्वितीय गोलमेज सम्मेलन में भागीदारी)। युग्म 3 गलत (सही: मद्रास की संधि (1769 ई.) — प्रथम आंग्ल-मैसूर युद्ध की समाप्ति (विजित क्षेत्रों की वापसी व पारस्परिक रक्षा समझौता))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक नारे एवं उद्घोष] सूची-I को सूची-II से सुमेलित कीजिए:\nA. ब्रिटिश साम्राज्य के ताबूत में कील   |   1. नेताजी सुभाष चंद्र बोस\nB. तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा   |   2. राम प्रसाद बिस्मिल (काकोरी कांड)\nC. आराम हराम है / 'Who lives if India dies?'   |   3. लाला लाजपत राय (साइमन कमीशन विरोध)\nD. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत)   |   4. पं. जवाहरलाल नेहरू","options":["A-1, B-3, C-4, D-2","A-3, B-1, C-4, D-2","A-3, B-4, C-1, D-2","A-3, B-1, C-2, D-4"],"correct":1,"explanation":"सही सुमेलन: ब्रिटिश साम्राज्य के ताबूत में कील (लाला लाजपत राय (साइमन कमीशन विरोध)), तुम मुझे खून दो, मैं तुम्हें आजादी दूँगा (नेताजी सुभाष चंद्र बोस), आराम हराम है / 'Who lives if India dies?' (पं. जवाहरलाल नेहरू), सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) (राम प्रसाद बिस्मिल (काकोरी कांड))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — वैदिक एवं आधुनिक नदियाँ] सूची-I को सूची-II से सुमेलित कीजिए:\nA. कुभा   |   1. गंडक\nB. सदानीरा   |   2. रावी\nC. असिक्नी   |   3. काबुल\nD. परुष्णी   |   4. चिनाब","options":["A-3, B-4, C-1, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4"],"correct":2,"explanation":"सही सुमेलन: कुभा (काबुल), सदानीरा (गंडक), असिक्नी (चिनाब), परुष्णी (रावी)।"},
  {"q":"[UPSC Prelims पैटर्न — सुधार संगठन एवं संस्थापक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. आर्य समाज (1875) : गोपाल कृष्ण गोखले\n2. सर्वेंट्स ऑफ इंडिया सोसाइटी (1905) : शिव नारायण अग्निहोत्री\n3. देव समाज (1887) : श्री नारायण गुरु\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: आर्य समाज (1875) — स्वामी दयानंद सरस्वती)। युग्म 2 गलत (सही: सर्वेंट्स ऑफ इंडिया सोसाइटी (1905) — गोपाल कृष्ण गोखले)। युग्म 3 गलत (सही: देव समाज (1887) — शिव नारायण अग्निहोत्री)।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. सरफरोशी की तमन्ना (अमर क्रांतिकारी गीत) : राम प्रसाद बिस्मिल (काकोरी कांड)\n2. वेदों की ओर लौटो / स्वदेशी-स्वराज प्रथम प्रयोग : स्वामी दयानंद सरस्वती\n3. ब्रिटिश साम्राज्य के ताबूत में कील : बाल गंगाधर तिलक (लखनऊ अधिवेशन, 1916)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (पटना के शायर बिस्मिल अजीमाबादी द्वारा रचित यह गजल काकोरी नायक राम प्रसाद बिस्मिल ने अमर की।) युग्म 2 सही (स्वामी दयानंद सरस्वती (मूलशंकर) ने 1875 में आर्य समाज व 'सत्यार्थ प्रकाश' की रचना की।) युग्म 3 गलत (सही: ब्रिटिश साम्राज्य के ताबूत में कील — लाला लाजपत राय (साइमन कमीशन विरोध))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विश्व इतिहास की प्रमुख घटनाएँ] सूची-I को सूची-II से सुमेलित कीजिए:\nA. बास्तील दुर्ग का पतन (14 जुलाई 1789)   |   1. कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार\nB. मार्टिन लूथर (जर्मनी)   |   2. इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण\nC. ओटो वॉन बिस्मार्क   |   3. फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)\nD. गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.)   |   4. प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)","options":["A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-4, C-1, D-2"],"correct":0,"explanation":"सही सुमेलन: बास्तील दुर्ग का पतन (14 जुलाई 1789) (फ्रांसीसी क्रांति का आरंभ ('स्वतंत्रता, समानता, बंधुत्व' आदर्श)), मार्टिन लूथर (जर्मनी) (कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार), ओटो वॉन बिस्मार्क (प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)), गौरवपूर्ण क्रांति / रक्तहीन क्रांति (1688 ई.) (इंग्लैंड में संसद की सर्वोच्चता व विलियम तृतीय-मेरी का सिंहासनारोहण)।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख आयोग एवं उद्देश्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. फ्लॉड आयोग (1940 ई., बंगाल) : बंगाल में स्थायी बंदोबस्त (जमींदारी प्रथा) की समीक्षा व 'तेभागा' (2/3 हिस्सा किसान को) अनुशंसा\n2. हंटर समिति (डिसऑर्डर्स इन्क्वायरी, 1919) : जलियाँवाला बाग व पंजाब उपद्रवों की जांच (चमनलाल सीतलवाड़ व सुल्तान अहमद भारतीय सदस्य)\n3. ह्विटली आयोग (1929 ई.) : 1854 पश्चात प्राथमिक एवं माध्यमिक शिक्षा की प्रगति की समीक्षा\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (सर फ्रांसिस फ्लॉड भू-राजस्व आयोग (1940) ने बंगाल की बटाईदार प्रथा व स्थायी बंदोबस्त दोषों को उजागर किया।) युग्म 2 सही (अक्टूबर 1919 में लॉर्ड विलियम हंटर की अध्यक्षता में समिति बनी, जबकि कांग्रेस ने मदन मोहन मालवीय समिति बनाई।) युग्म 3 गलत (सही: ह्विटली आयोग (1929 ई.) — भारतीय औद्योगिक श्रम (मजदूरों) की कार्यदशा व कल्याण स्थिति की जांच)।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. आराम हराम है / Who lives if India dies : जवाहरलाल नेहरू\n2. इंकलाब जिंदाबाद : भगत सिंह (रचयिता: हसरत मोहानी)\n3. सरफरोशी की तमन्ना... : श्यामलाल गुप्त 'पार्षद'\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (जवाहरलाल नेहरू ने स्वतंत्रता संग्राम व राष्ट्र-निर्माण के दौरान ये प्रेरक नारे दिए।) युग्म 2 सही (मूलतः मौलाना हसरत मोहानी (1921) द्वारा रचित इस नारे को भगत सिंह व बटुकेश्वर दत्त ने 1929 में अमर किया।) युग्म 3 गलत (सही: सरफरोशी की तमन्ना... — रामप्रसाद बिस्मिल (रचना: बिस्मिल अजीमाबादी))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — वैदिक शब्दावली एवं उपनिषद] सूची-I को सूची-II से सुमेलित कीजिए:\nA. गोधूम   |   1. गाय (न मारे जाने योग्य)\nB. अहं ब्रह्मास्मि   |   2. मुद्रा/मूल्य की इकाइयाँ\nC. निष्क व शतमन   |   3. गेहूँ\nD. अघन्या   |   4. बृहदारण्यक उपनिषद","options":["A-4, B-3, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2"],"correct":2,"explanation":"सही सुमेलन: गोधूम (गेहूँ), अहं ब्रह्मास्मि (बृहदारण्यक उपनिषद), निष्क व शतमन (मुद्रा/मूल्य की इकाइयाँ), अघन्या (गाय (न मारे जाने योग्य))।"},
  {"q":"[UPSC Prelims पैटर्न — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. फर्नओ नूनिज (पुर्तगाल) : देवराय प्रथम (विजयनगर, 1420 ई.)\n2. निकोलो कोंटी (इटली) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\n3. अफनासी निकितिन (रूस) : मुहम्मद बिन तुगलक (1333 ई.)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: फर्नओ नूनिज (पुर्तगाल) — अच्युतदेवराय (विजयनगर, ~1535 ई.))। युग्म 2 गलत (सही: निकोलो कोंटी (इटली) — देवराय प्रथम (विजयनगर, 1420 ई.))। युग्म 3 गलत (सही: अफनासी निकितिन (रूस) — बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.))।"},
  {"q":"[UPSC Prelims पैटर्न — मुगलकालीन प्रमुख युद्ध] निम्नलिखित युग्मों पर विचार कीजिए:\n1. चौसा का युद्ध (1539 ई.) : शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय\n2. खानवा युद्ध (1527 ई.) : बाबर बनाम राणा सांगा (मेवाड़)\n3. सामूगढ़ का युद्ध (1658 ई.) : नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई।) युग्म 2 सही (17 मार्च 1527 को खानवा में बाबर ने जिहाद का नारा देकर राणा सांगा के राजपूत संघ को हराया।) युग्म 3 गलत (सही: सामूगढ़ का युद्ध (1658 ई.) — औरंगजेब व मुराद बनाम दारा शिकोह)।"},
  {"q":"[UPSC Prelims पैटर्न — प्रमुख आयोग एवं उद्देश्य] निम्नलिखित युग्मों पर विचार कीजिए:\n1. फ्लॉड आयोग (1940 ई., बंगाल) : बंगाल में स्थायी बंदोबस्त (जमींदारी प्रथा) की समीक्षा व 'तेभागा' (2/3 हिस्सा किसान को) अनुशंसा\n2. बटलर समिति (1927 ई.) : ब्रिटिश भारत (सर्वोच्च शक्ति) तथा देशी रियासतों के बीच संबंध सुधारना\n3. वुड्स डिस्पैच (1854 ई.) : प्राथमिक स्तर पर देशी भाषा, उच्च स्तर पर अंग्रेजी, महिला शिक्षा व 3 प्रेसीडेंसी विश्वविद्यालय\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (सर फ्रांसिस फ्लॉड भू-राजस्व आयोग (1940) ने बंगाल की बटाईदार प्रथा व स्थायी बंदोबस्त दोषों को उजागर किया।) युग्म 2 सही (हरकोर्ट बटलर समिति ने कहा कि देशी रियासतों को बिना उनकी सहमति के जिम्मेदार भारतीय सरकार को नहीं सौंपा जाएगा।) युग्म 3 सही (1854 के वुड घोषणापत्र की सिफारिश पर 1857 में कलकत्ता, बंबई व मद्रास विश्वविद्यालय खुले।)।"},
  {"q":"[UPSC Prelims पैटर्न — विश्व इतिहास की प्रमुख घटनाएँ] निम्नलिखित युग्मों पर विचार कीजिए:\n1. इटली का फ्लोरेंस नगर : यूरोपीय पुनर्जागरण (Renaissance) का जन्मस्थल व मानववाद केंद्र\n2. मार्टिन लूथर (जर्मनी) : कैथोलिक चर्च के 'क्षमा-पत्रों' (Indulgences) का विरोध व प्रोटेस्टेंट सुधार\n3. ओटो वॉन बिस्मार्क : प्रशा के नेतृत्व में डेनमार्क-ऑस्ट्रिया-फ्रांस से तीन युद्धों द्वारा जर्मनी का एकीकरण (1871)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (14वीं-15वीं सदी में फ्लोरेंस (मेडिसी परिवार संरक्षण) से मानववाद, कला व तर्कशील पुनर्जागरण पूरे यूरोप में फैला।) युग्म 2 सही (मार्टिन लूथर ने बाइबिल का जर्मन अनुवाद किया व पोप की निरंकुश सत्ता को चुनौती दी।) युग्म 3 सही (चांसलर बिस्मार्क ने 'रक्त और लौह' नीति अपनाकर वर्साय के शीशमहल में 1871 में जर्मन साम्राज्य घोषित किया।)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — जैन-बौद्ध सिद्धांत] सूची-I को सूची-II से सुमेलित कीजिए:\nA. संघ में महिलाओं का प्रवेश   |   1. चतुर्थ बौद्ध संगीति (कुंडलवन, कश्मीर — वसुमित्र अध्यक्ष)\nB. स्याद्वाद / सप्तभंगी नय   |   2. सारनाथ (ऋषिपत्तन) में पाँच ब्राह्मणों को दिया गया प्रथम उपदेश\nC. धर्मचक्रप्रवर्तन   |   3. वैशाली (प्रजापति गौतमी व आम्रपाली)\nD. हीनयान और महायान विभाजन   |   4. जैन दर्शन (सत्य के अनेक पहलुओं का सापेक्ष सिद्धांत)","options":["A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1"],"correct":0,"explanation":"सही सुमेलन: संघ में महिलाओं का प्रवेश (वैशाली (प्रजापति गौतमी व आम्रपाली)), स्याद्वाद / सप्तभंगी नय (जैन दर्शन (सत्य के अनेक पहलुओं का सापेक्ष सिद्धांत)), धर्मचक्रप्रवर्तन (सारनाथ (ऋषिपत्तन) में पाँच ब्राह्मणों को दिया गया प्रथम उपदेश), हीनयान और महायान विभाजन (चतुर्थ बौद्ध संगीति (कुंडलवन, कश्मीर — वसुमित्र अध्यक्ष))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक युद्ध एवं परिणाम] सूची-I को सूची-II से सुमेलित कीजिए:\nA. करनाल का युद्ध (1739 ई.)   |   1. दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया\nB. दाशराज्ञ युद्ध (परुष्णी नदी)   |   2. अहमद शाह अब्दाली ने सदाशिवराव भाऊ के नेतृत्व वाली मराठा सेना को हराया\nC. पानीपत का तृतीय युद्ध (1761 ई.)   |   3. नादिर शाह ने मुगल सम्राट मुहम्मद शाह 'रंगीला' की सेना को हराया\nD. तालीकोटा का युद्ध (1565 ई.)   |   4. राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया","options":["A-3, B-2, C-4, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1"],"correct":3,"explanation":"सही सुमेलन: करनाल का युद्ध (1739 ई.) (नादिर शाह ने मुगल सम्राट मुहम्मद शाह 'रंगीला' की सेना को हराया), दाशराज्ञ युद्ध (परुष्णी नदी) (राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया), पानीपत का तृतीय युद्ध (1761 ई.) (अहमद शाह अब्दाली ने सदाशिवराव भाऊ के नेतृत्व वाली मराठा सेना को हराया), तालीकोटा का युद्ध (1565 ई.) (दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया)।"},
  {"q":"[UPSC Prelims पैटर्न — पत्र-पत्रिकाएँ एवं संपादक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. द बंगाली (The Bengalee) : सुरेंद्रनाथ बनर्जी\n2. हिंदू पैट्रियट (नील विद्रोह समर्थक) : पं. जुगल किशोर शुक्ल\n3. उदंत मार्तंड (1826, प्रथम हिंदी पत्र) : मौलाना अबुल कलाम आजाद\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (सुरेंद्रनाथ बनर्जी ने 1879 से 'द बंगाली' का संपादन कर सिविल सेवा व संवैधानिक सुधारों की आवाज उठाई।) युग्म 2 गलत (सही: हिंदू पैट्रियट (नील विद्रोह समर्थक) — हरिश्चंद्र मुखर्जी)। युग्म 3 गलत (सही: उदंत मार्तंड (1826, प्रथम हिंदी पत्र) — पं. जुगल किशोर शुक्ल)।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक नारे एवं उद्घोष] निम्नलिखित युग्मों पर विचार कीजिए:\n1. मेरे शरीर पर पड़ी एक-एक लाठी... : लाला लाजपत राय\n2. स्वराज मेरा जन्मसिद्ध अधिकार है : रामप्रसाद बिस्मिल (रचना: बिस्मिल अजीमाबादी)\n3. सरफरोशी की तमन्ना... : महात्मा गांधी\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (30 अक्टूबर 1928 को लाहौर में स्कॉट-सॉन्डर्स के लाठीचार्ज में घायल 'पंजाब केसरी' ने यह कहा।) युग्म 2 गलत (सही: स्वराज मेरा जन्मसिद्ध अधिकार है — बाल गंगाधर तिलक)। युग्म 3 गलत (सही: सरफरोशी की तमन्ना... — रामप्रसाद बिस्मिल (रचना: बिस्मिल अजीमाबादी))।"},
  {"q":"[UPSC Prelims पैटर्न — अशोक के प्रमुख शिलालेख] निम्नलिखित युग्मों पर विचार कीजिए:\n1. द्वितीय वृहद शिलालेख : मनुष्य व पशु चिकित्सा व्यवस्था एवं दक्षिण के सीमांत राज्यों (चोल, पांड्य, केरलपुत्र) का उल्लेख\n2. तेरहवाँ वृहद शिलालेख : कलिंग युद्ध का वर्णन (राज्याभिषेक के 8वें वर्ष) व 5 यूनानी समकालीन राजाओं का उल्लेख\n3. पाँचवाँ वृहद शिलालेख : राज्याभिषेक के 13वें वर्ष 'धम्म महामात्र' की नियुक्ति व बंदियों के कल्याण का निर्देश\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (द्वितीय वृहद शिलालेख में सीमांत दक्षिण राज्यों व औषधीय वृक्ष रोपण-चिकित्सा का वर्णन है।) युग्म 2 सही (तेरहवें वृहद शिलालेख में कलिंग युद्ध के पश्चाताप व यवन नरेशों में धम्म विजय वर्णित है।) युग्म 3 सही (पाँचवें वृहद शिलालेख में अशोक ने सर्वप्रथम धम्म महामात्रों की नियुक्ति का उल्लेख किया।)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विश्व इतिहास की प्रमुख घटनाएँ] सूची-I को सूची-II से सुमेलित कीजिए:\nA. वर्साय की संधि (1919)   |   1. ज्याँ-जैक रूसो\nB. यंग इटली (1831)   |   2. एडम स्मिथ\nC. वेल्थ ऑफ नेशंस (1776)   |   3. प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना\nD. द सोशल कॉन्ट्रैक्ट   |   4. ज्यूसेपे मैजिनी","options":["A-3, B-2, C-4, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-2, D-1","A-3, B-4, C-2, D-1"],"correct":3,"explanation":"सही सुमेलन: वर्साय की संधि (1919) (प्रथम विश्व युद्ध पश्चात जर्मनी पर कठोर शर्तें थोपना), यंग इटली (1831) (ज्यूसेपे मैजिनी), वेल्थ ऑफ नेशंस (1776) (एडम स्मिथ), द सोशल कॉन्ट्रैक्ट (ज्याँ-जैक रूसो)।"},
  {"q":"[UPSC Prelims पैटर्न — प्राचीन राजवंश एवं संस्थापक] निम्नलिखित युग्मों पर विचार कीजिए:\n1. कांची के पल्लव : सिंहविष्णु (छठी शती ई.)\n2. बादामी के चालुक्य : श्रीगुप्त (तीसरी शती ई.)\n3. गुप्त वंश : बिम्बिसार (राजधानी: राजगृह)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (सिंहविष्णु ('अवनि सिंह') ने कलाभ्रों को हराकर कांची के महान पल्लव साम्राज्य की नींव रखी।) युग्म 2 गलत (सही: बादामी के चालुक्य — पुलकेशिन प्रथम (जयसिंह के वंशज))। युग्म 3 गलत (सही: गुप्त वंश — श्रीगुप्त (तीसरी शती ई.))।"},
  {"q":"[UPSC/PCS सूची सुमेलन — प्राचीन ग्रंथ एवं रचयिता] सूची-I को सूची-II से सुमेलित कीजिए:\nA. पंचतंत्र   |   1. पाणिनि\nB. विक्रमांकदेवचरित   |   2. विष्णु शर्मा\nC. अष्टाध्यायी   |   3. तिरुवल्लुवर\nD. तिरुक्कुरल   |   4. बिल्हण","options":["A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3"],"correct":1,"explanation":"सही सुमेलन: पंचतंत्र (विष्णु शर्मा), विक्रमांकदेवचरित (बिल्हण), अष्टाध्यायी (पाणिनि), तिरुक्कुरल (तिरुवल्लुवर)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — शास्त्रीय नृत्य एवं राज्य] सूची-I को सूची-II से सुमेलित कीजिए:\nA. कुचिपुड़ी नृत्य   |   1. तमिलनाडु\nB. ओडिसी नृत्य   |   2. आंध्र प्रदेश\nC. भरतनाट्यम   |   3. असम\nD. सत्त्रिया नृत्य   |   4. ओडिशा","options":["A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3"],"correct":3,"explanation":"सही सुमेलन: कुचिपुड़ी नृत्य (आंध्र प्रदेश), ओडिसी नृत्य (ओडिशा), भरतनाट्यम (तमिलनाडु), सत्त्रिया नृत्य (असम)।"},
  {"q":"[UPSC CDS PYQ] दिल्ली सल्तनत के राजवंशों के शासनकाल का सही आरोही कालानुक्रम कौन-सा है?","options":["गुलाम -> तुगलक -> खिलजी -> लोदी -> सैय्यद","खिलजी -> गुलाम -> तुगलक -> सैय्यद -> लोदी","गुलाम -> खिलजी -> तुगलक -> सैय्यद -> लोदी","गुलाम -> खिलजी -> सैय्यद -> तुगलक -> लोदी"],"correct":2,"explanation":"दिल्ली सल्तनत के पाँच राजवंश क्रमशः गुलाम (1206-1290), खिलजी (1290-1320), तुगलक (1320-1414), सैय्यद (1414-1451) और लोदी (1451-1526) थे।"},
  {"q":"[UPSC Prelims पैटर्न — सल्तनत विभाग एवं सुल्तान] निम्नलिखित युग्मों पर विचार कीजिए:\n1. दीवान-ए-रिसालत : धार्मिक मामले, वजीफे व राजनयिक/विदेश पत्राचार\n2. दीवान-ए-खैरात : असहायों व गरीब कन्याओं की सहायता का दान विभाग (फिरोज तुगलक)\n3. दीवान-ए-अमीर कोही : बकाया राजस्व वसूली व भ्रष्ट अधिकारियों की जाँच (अलाउद्दीन)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (दीवान-ए-रिसालत का प्रमुख सद्र-उस-सुदूर विदेशी राजदूतों व धार्मिक अनुदान से जुड़ा था।) युग्म 2 सही (फिरोजशाह तुगलक ने गरीब व असहाय नागरिकों की मदद हेतु 'दीवान-ए-खैरात' बनाया।) युग्म 3 गलत (सही: दीवान-ए-अमीर कोही — कृषि विभाग व तकावी ऋण वितरण (मुहम्मद बिन तुगलक))।"},
  {"q":"[UPSC Prelims पैटर्न — कला, गुफाएँ एवं चित्रशैली] निम्नलिखित युग्मों पर विचार कीजिए:\n1. बनी-ठनी (मोरध्वज निहालचंद) : महाबलीपुरम / मामल्लपुरम (तमिलनाडु, पल्लव)\n2. सप्त पगोडा (पंच रथ) व गंगावतरण : अजंता गुफाएँ (महाराष्ट्र, वाकाटक युग)\n3. पद्मपाणि बोधिसत्त्व व मरणासन्न राजकुमारी : एलिफेंटा गुफाएँ (धारापुरी, मुंबई)\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: बनी-ठनी (मोरध्वज निहालचंद) — किशनगढ़ चित्रकला शैली (राजस्थान))। युग्म 2 गलत (सही: सप्त पगोडा (पंच रथ) व गंगावतरण — महाबलीपुरम / मामल्लपुरम (तमिलनाडु, पल्लव))। युग्म 3 गलत (सही: पद्मपाणि बोधिसत्त्व व मरणासन्न राजकुमारी — अजंता गुफाएँ (महाराष्ट्र, वाकाटक युग))।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों पर विचार कीजिए:\n1. पानीपत का द्वितीय युद्ध (1556 ई.) : पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया\n2. तराइन का प्रथम युद्ध (1191 ई.) : बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली\n3. खानवा का युद्ध (1527 ई.) : मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: पानीपत का द्वितीय युद्ध (1556 ई.) — अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया)। युग्म 2 गलत (सही: तराइन का प्रथम युद्ध (1191 ई.) — पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया)। युग्म 3 गलत (सही: खानवा का युद्ध (1527 ई.) — बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली)।"},
  {"q":"[UPSC Prelims PYQ] निम्नलिखित में से कौन 'देशी राज्य प्रजा परिषद' (ऑल इंडिया स्टेट्स पीपुल्स कॉन्फ्रेंस - 1927) के गठन से जुड़े प्रमुख नेताओं में से थे?","options":["बलवंतराय मेहता, मणिलाल कोठारी एवं जी.आर. अभ्यंकर","महात्मा गांधी एवं वल्लभभाई पटेल","मुहम्मद अली जिन्ना एवं तेज बहादुर सप्रू","जवाहरलाल नेहरू एवं सुभाष चंद्र बोस केवल"],"correct":0,"explanation":"1927 में बंबई में ऑल इंडिया स्टेट्स पीपुल्स कॉन्फ्रेंस की स्थापना बलवंतराय मेहता, मणिलाल कोठारी व जी.आर. अभ्यंकर के प्रयास से हुई (बाद में 1939 लुधियाना सत्र में नेहरू इसके अध्यक्ष बने)।"},
  {"q":"[UPSC/PCS सूची सुमेलन — मराठा अष्टप्रधान परिषद] सूची-I को सूची-II से सुमेलित कीजिए:\nA. वाकियानवीस (मंत्री)   |   1. मुख्य सैन्य कमांडर (पैदल व घुड़सवार नेतृत्व)\nB. सर-ए-नौबत (सेनापति)   |   2. वित्त एवं राजस्व लेखा-जोखा मंत्री\nC. सुमंत (दबीर)   |   3. राजा के दैनिक कार्य, गृह व गुप्तचर मामलों का विवरण रखना\nD. अमात्य (मजूमदार)   |   4. विदेश मंत्री (अंतर-राज्यीय संबंध)","options":["A-1, B-3, C-4, D-2","A-3, B-1, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-4, C-1, D-2"],"correct":1,"explanation":"सही सुमेलन: वाकियानवीस (मंत्री) (राजा के दैनिक कार्य, गृह व गुप्तचर मामलों का विवरण रखना), सर-ए-नौबत (सेनापति) (मुख्य सैन्य कमांडर (पैदल व घुड़सवार नेतृत्व)), सुमंत (दबीर) (विदेश मंत्री (अंतर-राज्यीय संबंध)), अमात्य (मजूमदार) (वित्त एवं राजस्व लेखा-जोखा मंत्री)।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों पर विचार कीजिए:\n1. तराइन का प्रथम युद्ध (1191 ई.) : पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया\n2. पानीपत का द्वितीय युद्ध (1556 ई.) : राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया\n3. दाशराज्ञ युद्ध (परुष्णी नदी) : राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (1191 ई. में तराइन के प्रथम युद्ध में पृथ्वीराज चौहान ने मुहम्मद गौरी को पराजित किया।) युग्म 2 गलत (सही: पानीपत का द्वितीय युद्ध (1556 ई.) — अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया)। युग्म 3 गलत (सही: दाशराज्ञ युद्ध (परुष्णी नदी) — राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया)।"},
  {"q":"[UPSC Prelims पैटर्न — वैदिक शब्दावली एवं उपनिषद] निम्नलिखित युग्मों पर विचार कीजिए:\n1. गोधूम : गेहूँ\n2. अहं ब्रह्मास्मि : बृहदारण्यक उपनिषद\n3. निष्क व शतमन : मुद्रा/मूल्य की इकाइयाँ\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (वैदिक संस्कृत साहित्य में 'गोधूम' गेहूँ तथा 'व्रीहि' चावल के लिए प्रयुक्त होता था।) युग्म 2 सही (बृहदारण्यक उपनिषद में 'अहं ब्रह्मास्मि' तथा याज्ञवल्क्य-गार्गी संवाद मिलता है।) युग्म 3 सही (ऋग्वैदिक आभूषण 'निष्क' और 'शतमन' उत्तर-वैदिक काल में विनिमय इकाई (सिक्का सदृश) बने।)।"}
]);
